    },
    bottomBarTextAr: {
      type: "text",
      label: "Bottom bar text (Arabic)",
      placeholder: "مثال: © ٢٠٢٦ متجري",
    },
    columns: {
      type: "array",
      label: "Footer columns",
      arrayFields: {
        title: { type: "text", label: "Column title (English)" },
        titleAr: { type: "text", label: "Column title (Arabic)" },
        links: {
          type: "array",
          label: "Links",
          arrayFields: {
            label: { type: "text", label: "Label (English)" },
            labelAr: { type: "text", label: "Label (Arabic)" },
            link: linkField({ label: "Destination" }),
          },
          defaultItemProps: {
            label: "New link",
            labelAr: "عنصر",
            link: EMPTY_LINK,
          },
          getItemSummary: (item: { label?: string; href?: string }) =>
            item?.label || item?.href || "Link",
        },
      },
      defaultItemProps: {
        title: "New column",
        titleAr: "عمود جديد",
        links: [{ label: "Link", labelAr: "رابط", link: EMPTY_LINK }],
      },
      getItemSummary: (item: { title?: string }) => item?.title || "Column",
    } as any,
    bottomLinks: {
      type: "array",
      label: "Bottom links",
      arrayFields: {
        label: { type: "text", label: "Label (English)" },
        labelAr: { type: "text", label: "Label (Arabic)" },
        link: linkField({ label: "Destination" }),
      },
      defaultItemProps: {
        label: "New link",
        labelAr: "عنصر",
        link: EMPTY_LINK,
      },
      getItemSummary: (item: { label?: string; href?: string }) =>
        item?.label || item?.href || "Link",
    } as any,
    backgroundColor: colorField({
      label: "Background color",
      description: "Empty = use theme default.",
    }),
    textColor: colorField({
      label: "Text color",
      description: "Empty = use theme default.",
    }),
  },
  defaultProps: {
    title: "متجري على SOOQ",
    variant: "commerce",
    language: "ar",
    visible: true,
    tagline: "",
    taglineAr: "",
    showBottomBar: true,
    bottomBarText: "",
    bottomBarTextAr: "",
    columns: DEFAULT_FOOTER_COLUMNS,
    bottomLinks: DEFAULT_FOOTER_BOTTOM_LINKS,
    backgroundColor: "",
    textColor: "",
  },
  render: ({
    title,
    variant,
    language,
    visible,
    tagline,
    taglineAr,
    showBottomBar,
    bottomBarText,
    bottomBarTextAr,
    columns,
    bottomLinks,
    backgroundColor,
    textColor,
    puck,
  }) => {
    return (
      <Footer
        siteTitle={title}
        variant={variant}
        columns={columns}
        language={language}
        editMode={!!puck.isEditing}
        visible={visible}
        showBottomBar={showBottomBar}
        bottomBarText={bottomBarText}
        bottomBarTextAr={bottomBarTextAr}
        tagline={tagline}
        taglineAr={taglineAr}
        bottomLinks={bottomLinks}
        backgroundColor={backgroundColor || undefined}
        textColor={textColor || undefined}
      />
    );
  },
};

