    lineHeightFixed: "1.6",
    fontStyle: "normal",
    textTransform: "none",
    maxWidth: "none",
  },
  render: (props) => {
    const {
      text,
      textAlign,
      fontFamily,
      fontSizeMode,
      fontSizeTheme,
      fontSizeFixed,
      fontWeightMode,
      fontWeightTheme,
      fontWeightFixed,
      lineHeightMode,
      lineHeightTheme,
      lineHeightFixed,
      fontStyle,
      textTransform,
      maxWidth,
