    name: "main-menu",
    title: { ar: "القائمة", en: "Menu" },
    showTitle: true,
    side: "left",
    width: "medium",
    animation: "slide",
    animationDuration: 260,
    trigger: "button",
    triggerLabel: { ar: "القائمة", en: "Menu" },
    triggerIcon: "menu",
    overlay: true,
    overlayOpacity: 50,
    closeOnOverlayClick: true,
    closeOnEsc: true,
    showCloseButton: true,
    startOpen: false,
    visible: true,
