  defaultProps: {
    title: "متجري على SOOQ",
    variant: "commerce",
    language: "ar",
    visible: true,
    brandHref: "/",
    links: DEFAULT_HEADER_LINKS,
    backgroundColor: "",
    textColor: "",
    showDrawerButton: false,
    drawerButtonIcon: "menu",
    drawerName: "site-drawer",
  },
  render: ({
    title,
    variant,
    language,
    visible,
    brandHref,
    links,
    backgroundColor,
    textColor,
    showDrawerButton,
    drawerButtonIcon,
    drawerName,
    puck,
  }) => {
    return (
      <Header
        editMode={!!puck.isEditing}
        variant={variant}
        siteTitle={title}
        links={links}
        language={language}
        visible={visible}
        brandHref={brandHref}
        backgroundColor={backgroundColor || undefined}
        textColor={textColor || undefined}
        showDrawerButton={showDrawerButton}
        drawerButtonIcon={drawerButtonIcon}
        drawerName={drawerName || "site-drawer"}
      />
    );
  },
};

