import { colorField } from "../../fields/ColorField";
import styles from "./styles.module.css";

const getClassName = getClassNameFactory("Accordion", styles);

type AccordionItem = {
  title: string;
  body: string;
  open: boolean;
};

export type AccordionProps = WithLayout<{
  heading: string;
  description: string;
  items: AccordionItem[];
  variant: "soft" | "outline" | "minimal";
  fontFamily: "body" | "option1" | "option2";
  backgroundColor: string;
  textColor: string;
  accentColor: string;
  borderRadius: string;
}>;

const AccordionInner: ComponentConfig<AccordionProps> = {
  label: "Accordion",
  fields: {
    heading: { type: "text", label: "Heading" },
    description: { type: "textarea", label: "Description" },
    variant: {
      type: "radio",
      label: "Variant",
      options: [
