          type: "radio",
          label: "Start open",
          options: [
            { label: "No", value: false },
            { label: "Yes", value: true },
          ],
        },
      },
      defaultItemProps: {
        title: "Question",
        body: "Answer",
        open: false,
      },
      getItemSummary: (item: AccordionItem) => item.title || "Item",
    },
